interface MembershipPlan{int getMonths();double calculateFee();String getName();}class MonthlyPlan implements MembershipPlan{public int getMonths(){return 1;}public double calculateFee(){return 1000;}public String getName(){return "Monthly";}}class QuarterlyPlan implements MembershipPlan{public int getMonths(){return 3;}public double calculateFee(){return 3000*.90;}public String getName(){return "Quarterly";}}class AnnualPlan implements MembershipPlan{public int getMonths(){return 12;}public double calculateFee(){return 12000*.75;}public String getName(){return "Annual";}}
class Member{String name;Member(String n){name=n;}}class Membership{private Member member;private MembershipPlan plan;private String status="Active";Membership(Member m,MembershipPlan p){member=m;plan=p;System.out.printf("%s membership created for %s. Fee: ₹%.2f. Status: %s.%n",p.getName(),m.name,p.calculateFee(),status);}public void checkIn(){if(status.equals("Active"))System.out.println(member.name+" checked in successfully.");else System.out.println("Check-in denied: "+member.name+"'s membership is "+status+".");}public void freeze(){if(status.equals("Expired"))System.out.println("Cannot freeze an Expired membership.");else if(status.equals("Frozen"))System.out.println(member.name+"'s membership is already Frozen.");else{status="Frozen";System.out.println(member.name+"'s membership frozen.");System.out.println("Status: "+status+".");}}public void unfreeze(){if(status.equals("Expired"))System.out.println("Cannot unfreeze an Expired membership.");else if(status.equals("Frozen")){status="Active";System.out.println(member.name+"'s membership unfrozen.");System.out.println("Status: "+status+".");}else System.out.println("Membership is already Active.");}public void expire(){status="Expired";System.out.println(member.name+"'s membership expired.");System.out.println("Status: "+status+".");}}
public class FitZoneMembership{public static void main(String[] args){Member a=new Member("Asha"),r=new Member("Ravi");Membership x=new Membership(a,new QuarterlyPlan()),y=new Membership(r,new MonthlyPlan());x.checkIn();x.freeze();x.checkIn();y.expire();y.freeze();}}